// Dos formas de contar cotizaciones: en la memoria de la instancia o en un almacén externo.
function azar(semilla) { let a = semilla; return () => { a |= 0; a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }

const almacen = { cotizaciones: 0 };            // la base de datos: vive afuera de las funciones
function crearInstancia() { return { local: 0 }; } // la memoria de un entorno de ejecución

function handler(instancia, evento, deps) {
  instancia.local += 1;                        // mal: parece un contador, es una variable de este entorno
  deps.almacen.cotizaciones += 1;              // bien: el estado que importa va afuera
  return { cp: evento.cp, local: instancia.local, total: deps.almacen.cotizaciones };
}

const r = azar(7);
let instancias = [crearInstancia(), crearInstancia(), crearInstancia()];
console.log('pedido  instancia  contador-local  contador-almacén');
for (let i = 1; i <= 12; i++) {
  if (r() < 0.25) instancias[Math.floor(r() * 3)] = crearInstancia(); // la plataforma recicla un entorno cuando quiere
  const k = Math.floor(r() * 3);                                       // y reparte los pedidos como quiere
  const out = handler(instancias[k], { cp: 1000 + i }, { almacen });
  console.log(String(i).padStart(6), String(k).padStart(10), String(out.local).padStart(15), String(out.total).padStart(17));
}

// Costo mensual de una función por uso, con la lista de precios de AWS Lambda (x86, us-east-1, publicada el 2026-11-11)
const P = { porMillon: 0.20, gbSeg: 0.0000166667, gratisReq: 1_000_000, gratisGbSeg: 400_000 };
function costoFuncion({ req, ms, mb }) {
  const gbSeg = req * (ms / 1000) * (mb / 1024);
  const compute = Math.max(0, gbSeg - P.gratisGbSeg) * P.gbSeg;   // sin los escalones de descuento: los primeros 6.000 millones de GB-s
  const pedidos = Math.max(0, req - P.gratisReq) * P.porMillon / 1e6;
  return { gbSeg, usd: compute + pedidos };
}
const SERVIDOR = 15; // USD/mes: SUPUESTO de ejemplo para una máquina chica, no un precio de lista
console.log('pedidos/mes      GB-s      función USD   servidor USD');
for (const req of [100_000, 1_000_000, 10_000_000, 30_000_000, 100_000_000]) {
  const c = costoFuncion({ req, ms: 120, mb: 256 });
  console.log(String(req).padStart(11), c.gbSeg.toFixed(0).padStart(10), c.usd.toFixed(2).padStart(14), String(SERVIDOR).padStart(14));
}
// punto de cruce: pedidos por mes donde la función iguala al servidor (cada tramo, con 120 ms y 256 MB)
let lo = 1e6, hi = 1e10;
for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; (costoFuncion({ req: m, ms: 120, mb: 256 }).usd < SERVIDOR ? lo = m : hi = m); }
console.log('cruce a los', Math.round(lo).toLocaleString('es-AR'), 'pedidos por mes =', (lo / (30 * 86400)).toFixed(1), 'por segundo promedio');
// lo mismo con 3 s por pedido (esperando una API externa) y 512 MB
let l2 = 1e5, h2 = 1e10;
for (let i = 0; i < 60; i++) { const m = (l2 + h2) / 2; (costoFuncion({ req: m, ms: 3000, mb: 512 }).usd < SERVIDOR ? l2 = m : h2 = m); }
console.log('con 3000 ms y 512 MB el cruce baja a', Math.round(l2).toLocaleString('es-AR'), 'pedidos por mes =', (l2 / (30 * 86400)).toFixed(2), 'por segundo');

// Cuánto cuesta UN pedido según la memoria elegida, para dos tipos de trabajo (duraciones inventadas para el ejemplo)
const GB_SEG = 0.0000166667, POR_PEDIDO = 0.20 / 1e6;
const costo = (ms, mb) => (ms / 1000) * (mb / 1024) * GB_SEG + POR_PEDIDO;
const filas = [
  // memoria, ms si el trabajo es de CPU (se reparte con la CPU), ms si espera a otra API (no cambia)
  [128, 800, 3000], [256, 400, 3000], [512, 200, 3000], [1024, 100, 3000],
];
console.log('memoria   CPU: ms   CPU: µUSD/pedido   espera: ms   espera: µUSD/pedido');
for (const [mb, msCpu, msEspera] of filas)
  console.log(String(mb).padStart(6), String(msCpu).padStart(9), (costo(msCpu, mb) * 1e6).toFixed(2).padStart(18), String(msEspera).padStart(12), (costo(msEspera, mb) * 1e6).toFixed(2).padStart(20));
